column3:
(None, None) => {
    // 这块盘上的两份都废了，但别的盘各自还带着一份完整的系统配置：跳过它，别让整池挂不上；记下来交给调用方。
    devices_without_a_mountable_system_configuration_slot.push(device);
    continue;
}

