column4:
(None, None) => {
    if chosen.is_none() {
        return Err(RecoveryFailure::NoValidSystemConfiguration {
            first_device_with_no_valid_system_configuration_slot: device,
        });
    }
    devices_without_a_mountable_system_configuration_slot.push(device);
    continue;
}
